import { use, useCallback, useEffect, useRef, useState } from 'react';
import {
  OpenChangeReason,
  safePolygon,
  useDelayGroup,
  useDismiss,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
} from '@floating-ui/react';
import { useId } from '@mantine/hooks';
import { HoverCardGroupContext } from './HoverCardGroup/HoverCardGroup';

interface UseHoverCard {
  openDelay?: number;
  closeDelay?: number;
  opened?: boolean;
  defaultOpened?: boolean;
  onOpen?: () => void;
  onClose?: () => void;
  events: { hover: boolean; focus: boolean; touch: boolean };
  interactive: boolean;
  closeOnEscape: boolean;
  closeOnClickOutside: boolean;
  onDismiss?: () => void;
  id?: string;
}

export function useHoverCard(settings: UseHoverCard) {
  const [uncontrolledOpened, setUncontrolledOpened] = useState(settings.defaultOpened);
  const controlled = typeof settings.opened === 'boolean';
  const opened = controlled ? settings.opened : uncontrolledOpened;
  const withinGroup = use(HoverCardGroupContext).withinGroup;
  const uid = useId(settings.id);

  const openedRef = useRef(opened);
  openedRef.current = opened;

  const openTimeout = useRef(-1);
  const closeTimeout = useRef(-1);
  const targetRef = useRef<HTMLElement | null>(null);

  const assignTarget = useCallback((node: HTMLElement | null) => {
    targetRef.current = node;
  }, []);

  const clearTimeouts = useCallback(() => {
    window.clearTimeout(openTimeout.current);
    window.clearTimeout(closeTimeout.current);
  }, []);

  const onChange = useCallback(
    (_opened: boolean) => {
      if (openedRef.current === _opened) {
        return;
      }

      openedRef.current = _opened;
      setUncontrolledOpened(_opened);

      if (_opened) {
        setCurrentId(uid);
        settings.onOpen?.();
      } else {
        settings.onClose?.();
      }
    },
    [uid, settings.onOpen, settings.onClose]
  );

  const onOpenChange = useCallback(
    (_opened: boolean, _event?: Event, reason?: OpenChangeReason) => {
      const wasOpened = openedRef.current;
      onChange(_opened);

      if (wasOpened && !_opened && (reason === 'escape-key' || reason === 'outside-press')) {
        settings.onDismiss?.();
      }
    },
    [onChange, settings.onDismiss]
  );

  const { context, refs } = useFloating({
    open: opened,
    onOpenChange,
  });

  const { delay: groupDelay, setCurrentId } = useDelayGroup(context, { id: uid });

  const { getReferenceProps, getFloatingProps } = useInteractions([
    useHover(context, {
      enabled: settings.events.hover,
      delay: withinGroup ? groupDelay : { open: settings.openDelay, close: settings.closeDelay },
      mouseOnly: !settings.events.touch,
      handleClose: settings.interactive ? safePolygon() : null,
    }),
    useFocus(context, { enabled: settings.events.focus, visibleOnly: true }),
    useDismiss(context, {
      escapeKey: settings.closeOnEscape,
      outsidePress: settings.closeOnClickOutside,
    }),
  ]);

  const openDropdown = useCallback(() => {
    clearTimeouts();
    if (!settings.openDelay) {
      onChange(true);
    } else {
      openTimeout.current = window.setTimeout(() => onChange(true), settings.openDelay);
    }
  }, [clearTimeouts, settings.openDelay, onChange]);

  const closeDropdown = useCallback(() => {
    clearTimeouts();
    if (!settings.closeDelay) {
      onChange(false);
    } else {
      closeTimeout.current = window.setTimeout(() => onChange(false), settings.closeDelay);
    }
  }, [clearTimeouts, settings.closeDelay, onChange]);

  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  useEffect(() => () => clearTimeouts(), [clearTimeouts]);

  useEffect(() => {
    if (!opened || withinGroup || typeof IntersectionObserver === 'undefined') {
      return undefined;
    }

    const node = targetRef.current;
    if (!node) {
      return undefined;
    }

    const observer = new IntersectionObserver(() => {
      if (!node.isConnected || node.getClientRects().length === 0) {
        clearTimeouts();
        onChangeRef.current(false);
      }
    });

    observer.observe(node);
    return () => observer.disconnect();
  }, [opened, withinGroup, clearTimeouts]);

  return {
    opened,
    dropdownId: `${uid}-dropdown`,
    reference: refs.setReference,
    floating: refs.setFloating,
    assignTarget,
    getReferenceProps,
    getFloatingProps,
    openDropdown,
    closeDropdown,
  };
}
